// Bundled deploy bytecode for the opt-in 4337 module (assets/bytecode/*.json,
// generated by build/gen-4337-bytecode.mjs). Every load re-verifies the sha256
// of the creation code and the CREATE2 address so a tampered asset can never be
// deployed.
import { createHash } from "node:crypto";
import { concat, encodeAbiParameters, getAddress, getContractAddress, keccak256, type Address, type Hex } from "viem";
import { assetJson } from "../core/assets.ts";
import { UpError } from "../core/errors.ts";

export interface EntryPointAsset {
  name: "EntryPointV06";
  version: string;
  provenance: Record<string, unknown>;
  creationCode: Hex;
  creationCodeSha256: string;
  creationCodeKeccak256: Hex;
  deployment: { method: "create2-nick"; factory: Address; salt: Hex; initCodeHash: Hex; address: Address };
  runtimeCodeHash: Hex;
  runtimeCodeHashLiveCheck?: unknown;
}

export interface ExtensionAsset {
  name: "Extension4337";
  version: string;
  provenance: Record<string, unknown>;
  creationCode: Hex;
  creationCodeSha256: string;
  creationCodeKeccak256: Hex;
  deployment: {
    method: "create2-nick";
    factory: Address;
    saltPreimage: string;
    salt: Hex;
    canonical: { entryPoint: Address; initCodeHash: Hex; address: Address; runtimeCodeHash: Hex };
  };
}

export function sha256Hex(code: Hex): string {
  return createHash("sha256").update(Buffer.from(code.slice(2), "hex")).digest("hex");
}

export function create2Address(factory: Address, salt: Hex, initCode: Hex): Address {
  return getContractAddress({ opcode: "CREATE2", from: factory, salt, bytecode: initCode });
}

function integrity(name: string, code: Hex, sha: string, kec: Hex): void {
  if (sha256Hex(code) !== sha || keccak256(code) !== kec) {
    throw new UpError("INTERNAL", `bundled ${name} bytecode failed its integrity check (sha256/keccak256 mismatch); refusing to deploy`, {
      hint: "reinstall the skill package; never edit assets/bytecode by hand (regenerate with build/gen-4337-bytecode.mjs)",
    });
  }
}

let epCache: EntryPointAsset | undefined;
export function entryPointAsset(): EntryPointAsset {
  if (epCache) return epCache;
  const a = assetJson<EntryPointAsset>("bytecode", "EntryPointV06.json");
  integrity("EntryPoint v0.6", a.creationCode, a.creationCodeSha256, a.creationCodeKeccak256);
  const addr = create2Address(a.deployment.factory, a.deployment.salt, a.creationCode);
  if (addr !== getAddress(a.deployment.address)) throw new UpError("INTERNAL", `bundled EntryPoint v0.6 bytecode does not produce ${a.deployment.address} (got ${addr})`);
  return (epCache = a);
}

let extCache: ExtensionAsset | undefined;
export function extensionAsset(): ExtensionAsset {
  if (extCache) return extCache;
  const a = assetJson<ExtensionAsset>("bytecode", "Extension4337.json");
  integrity("Extension4337", a.creationCode, a.creationCodeSha256, a.creationCodeKeccak256);
  const c = a.deployment.canonical;
  const addr = create2Address(a.deployment.factory, a.deployment.salt, extensionInitCode(c.entryPoint, a));
  if (addr !== getAddress(c.address)) throw new UpError("INTERNAL", `bundled Extension4337 bytecode does not produce ${c.address} (got ${addr})`);
  return (extCache = a);
}

/** creationCode ++ abi.encode(entryPoint) */
export function extensionInitCode(entryPoint: Address, a: ExtensionAsset = extensionAsset()): Hex {
  return concat([a.creationCode, encodeAbiParameters([{ type: "address" }], [entryPoint])]);
}

/** Deterministic Extension4337 address for an EntryPoint (Nick's factory + the documented salt). */
export function extensionAddressFor(entryPoint: Address): Address {
  const a = extensionAsset();
  return create2Address(a.deployment.factory, a.deployment.salt, extensionInitCode(entryPoint, a));
}

/** Expected runtime code hash of the bundled Extension4337 for an EntryPoint (known only for the canonical v0.6 one). */
export function extensionRuntimeHashFor(entryPoint: Address): Hex | undefined {
  const c = extensionAsset().deployment.canonical;
  return c.entryPoint.toLowerCase() === entryPoint.toLowerCase() ? c.runtimeCodeHash : undefined;
}
